#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int to, rev;
    long long capacity, cost;
    Edge(int to, int rev, long long capacity, long long cost)
        : to(to), rev(rev), capacity(capacity), cost(cost) {}
};

struct MinCostFlowGraph {
    int n;
    vector<vector<Edge>> adj;
    vector<pair<int, int>> edges_pos;
    vector<long long> potential;
    vector<int> prev_vertex, prev_edge;
    vector<bool> visited;

    MinCostFlowGraph(int n) : n(n), adj(n), potential(n, 0), prev_vertex(n), prev_edge(n), visited(n, false) {}

    void add_edge(int from_node, int to_node, long long capacity, long long cost) {
        adj[from_node].emplace_back(to_node, (int)adj[to_node].size(), capacity, cost);
        adj[to_node].emplace_back(from_node, (int)adj[from_node].size() - 1, 0, -cost);
        edges_pos.emplace_back(from_node, (int)adj[from_node].size() - 1);
    }

    Edge get_edge(int i) {
        auto [u, idx] = edges_pos[i];
        auto &e = adj[u][idx];
        auto &re = adj[e.to][e.rev];
        return Edge(u, e.to, e.capacity + re.capacity, e.cost);
    }

    vector<Edge> all_edges() {
        vector<Edge> result;
        for (int i = 0; i < (int)edges_pos.size(); ++i) {
            auto [u, idx] = edges_pos[i];
            auto &e = adj[u][idx];
            auto &re = adj[e.to][e.rev];
            result.emplace_back(u, e.to, e.capacity + re.capacity, e.cost);
        }
        return result;
    }

    bool find_shortest_path(int s, int t, vector<long long> &dist, vector<int> &prev_vertex, vector<int> &prev_edge) {
        fill(dist.begin(), dist.end(), LLONG_MAX);
        fill(prev_vertex.begin(), prev_vertex.end(), -1);
        fill(prev_edge.begin(), prev_edge.end(), -1);
        fill(visited.begin(), visited.end(), false);
        dist[s] = 0;
        using pli = pair<long long, int>;
        priority_queue<pli, vector<pli>, greater<pli>> pq;
        pq.emplace(0, s);
        while (!pq.empty()) {
            auto [d, v] = pq.top(); pq.pop();
            if (visited[v]) continue;
            visited[v] = true;
            if (v == t) break;
            for (int i = 0; i < (int)adj[v].size(); ++i) {
                auto &e = adj[v][i];
                if (e.capacity == 0 || visited[e.to]) continue;
                long long new_dist = dist[v] + e.cost;
                if (dist[e.to] > new_dist) {
                    dist[e.to] = new_dist;
                    prev_vertex[e.to] = v;
                    prev_edge[e.to] = i;
                    pq.emplace(dist[e.to], e.to);
                }
            }
        }
        return visited[t];
    }

    vector<pair<long long, long long>> min_cost_flow(int s, int t, long long flow_limit = LLONG_MAX) {
        long long flow = 0, cost = 0;
        vector<pair<long long, long long>> results;
        results.emplace_back(flow, cost);
        vector<long long> dist(n);
        while (flow < flow_limit) {
            if (!find_shortest_path(s, t, dist, prev_vertex, prev_edge))
                break;
            long long c = flow_limit - flow;
            for (int v = t; v != s; v = prev_vertex[v]) {
                auto &e = adj[prev_vertex[v]][prev_edge[v]];
                c = min(c, e.capacity);
            }
            for (int v = t; v != s; v = prev_vertex[v]) {
                auto &e = adj[prev_vertex[v]][prev_edge[v]];
                e.capacity -= c;
                adj[e.to][e.rev].capacity += c;
            }
            long long delta = -potential[s];
            flow += c;
            cost += c * delta;
            if (results.back().second == cost)
                results.pop_back();
            results.emplace_back(flow, cost);
        }
        return results;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    vector<long long> data(7);
    for (int i = 0; i < 7; ++i) cin >> data[i];
    int n = 8;
    MinCostFlowGraph g(n);
    long long a1 = data[0], a2 = data[1], a3 = data[2];
    long long b1 = data[3], b2 = data[4], b3 = data[5];

    g.add_edge(0, 1, a1, 0);
    g.add_edge(0, 2, a2, 0);
    g.add_edge(0, 3, a3, 0);
    g.add_edge(4, 7, b1, 0);
    g.add_edge(5, 7, b2, 0);
    g.add_edge(6, 7, b3, 0);

    for (int i = 1; i <= 3; ++i) {
        for (int j = 4; j <= 6; ++j) {
            long long cost = ((j - i) % 3 == 1) ? 1 : 0;
            g.add_edge(i, j, LLONG_MAX, cost);
        }
    }

    auto flow_result = g.min_cost_flow(0, 7);
    long long ans1 = flow_result.back().first;
    long long ans2 = min(a1, b2) + min(a2, b3) + min(a3, b1);
    cout << ans1 << " " << ans2 << "\n";
    return 0;
}

